{"command":"cd /exercise && cat > binary.js <<'EOF'
export class Binary {
  constructor(binary) {
    this.binary = binary;
  }

  toDecimal() {
    if (typeof this.binary !== 'string' || this.binary.length === 0) {
      return null;
    }

    let decimal = 0;

    for (const digit of this.binary) {
      if (digit !== '0' && digit !== '1') {
        return null;
      }

      decimal = decimal * 2 + (digit === '1' ? 1 : 0);
    }

    return decimal;
  }
}
EOF
